import { AsyncLocalStorage } from 'node:async_hooks';

@Module({
  providers: [{ provide: AsyncLocalStorage, useValue: new AsyncLocalStorage() }],
  exports: [AsyncLocalStorage],
})
export class AlsModule {}

@Module({
  imports: [AlsModule],
  providers: [CatsService],
  controllers: [CatsController],
})
export class AppModule implements NestModule {
  constructor(private readonly als: AsyncLocalStorage) {}

  configure(consumer: MiddlewareConsumer) {
    consumer
      .apply((req, res, next) => {
        this.als.run({ userId: req.headers['x-user-id'] }, () => next());
      })
      .forRoutes('*path');
  }
}

@Injectable()
export class CatsService {
  constructor(
    private readonly tracerService: TracerService<RequestStore>,
    private readonly catsRepository: CatsRepository,
  ) {}

  getCatForUser() {
    const userId = this.tracerService.getAttribute('userId');
    return this.catsRepository.getForUser(userId);
  }

  enableBeta() {
    this.tracerService.setAttribute('flags.betaCheckout', true);
  }
}
